const devis = $('Fetch Devis Source').all().map(i => i.json);
const tracking = $('Read Supabase Tracking').all().map(i => i.json);
const trackingMap = {};
tracking.forEach(t => { trackingMap[t.id_devis] = t; });

const today = new Date();
const RELANCE_DELAYS = [5, 12, 20];

const eligible = [];
for (const d of devis) {
  if (d.statut !== 'envoyé') continue;
  const t = trackingMap[d.id_devis] || { nb_relances: 0, derniere_relance: null };
  if (t.statut_relance === 'stop' || t.statut_relance === 'transformé' || t.statut_relance === 'perdu') continue;
  if (t.nb_relances >= 3) continue;

  const dateEnvoi = new Date(d.date_envoi);
  const joursEcoules = Math.floor((today - dateEnvoi) / 86400000);
  const targetDelay = RELANCE_DELAYS[t.nb_relances];

  if (joursEcoules >= targetDelay) {
    eligible.push({ ...d, nb_relances_actuel: t.nb_relances, jours_ecoules: joursEcoules });
  }
}

return eligible.map(e => ({ json: e }));

