// Générer rapport uniquement le vendredi
const today = new Date();
if (today.getDay() !== 5) return [{ json: { skip: true } }];

// Agréger les données du run
const items = $input.all();
const rapport = {
  date: today.toISOString().split('T')[0],
  nb_relances_envoyees: items.filter(i => !i.json.skip).length,
  devis_relances: items.filter(i => !i.json.skip).map(i => ({
    id: i.json.id_devis || 'N/A',
    client: i.json.client_nom || 'N/A',
    montant: i.json.montant_ht || 0,
    relance_n: (i.json.nb_relances_actuel || 0) + 1
  }))
};

const totalMontant = rapport.devis_relances.reduce((s, d) => s + d.montant, 0);
const lignes = rapport.devis_relances.map(d =>
  `  - ${d.client} | ${d.id} | ${d.montant}€ HT | Relance ${d.relance_n}/3`
).join('\n');

rapport.email_body = `Rapport hebdomadaire relances devis — ${rapport.date}\n\n` +
  `Relances envoyées cette semaine : ${rapport.nb_relances_envoyees}\n` +
  `Volume devis relancés : ${totalMontant.toFixed(0)} € HT\n\n` +
  `Détail :\n${lignes}\n\n` +
  `Action requise : mettre à jour le statut des devis transformés ou perdus dans votre fichier de suivi.`;

return [{ json: rapport }];

